    "guide": "이 책은 역사 이야기를 읽는 모임이라서 정답을 맞히는 자리가 아니에요. 첫 모임에서는 책 전체의 그림(교회의 강)을 편하게 소개해 주세요. 막히기 쉬운 곳이 셋 있어요. 첫째, 1054년을 \"그날 갈라선 날\"로 배운 사람과 \"오래 멀어진 끝\"으로 들은 사람이 함께 있을 수 있어요. 두 이야기 모두 자료가 있다고만 말해 주세요. 그 뒤에도 서로를 교회로 여겼는지는 학자마다 갈리고 자료가 다 말해 주지 않으니, 모른다고 해도 괜찮아요. 둘째, 신경의 \"및 아들에게서\" 같은 낱말이 나오면 깊이 설명하지 말고 \"서쪽 신경에만 한 줄이 더 있다\"는 사실만 짚어 주세요. 셋째, 교황의 자리, 성찬을 어떻게 이해하는지, 성인과 성모 공경, 오늘 교회들 사이의 대화와 일치 운동이 어떻게 되어 가는지 같은 질문이 나오면 이 책이 다루지 않으니 교역자와 나누자고 안내해 주세요. 어느 교회가 옳은지 가리거나 하나가 되어야 한다고 다그치는 분위기가 되지 않게 해 주세요. 성경과 역사 자료가 다 말하지 않는 것은 모른다고 말해도 돼요. 마지막 읽을 글 끝 문단 \"우리와 같은 것, 다른 것\"에서 우리 교회의 입장을 더하는 일은 교역자 몫이에요.",
