            "t": "고린도전서 12:12~13에서 바울은 많은 지체가 어떻게 한 몸이 된다고 말하나요? 어떤 사람들이 그 한 몸 안에 들어 있다고 하나요?",
            "sub": "\"한 몸\", \"여럿\", \"한 성령\"이라는 말에 표시하며 읽어 보아요.",
