            "t": "바울은 12절에서 몸의 이야기를 하다가 마지막에 그 몸의 이름을 \"그리스도\"라고 부릅니다. 27절은 고린도 사람들에게 너희가 그리스도의 몸이라고 말합니다. 이 몸이 하나인 까닭은 서로 닮아서가 아니라 한 성령으로 이루어졌기 때문이라고 13절은 말합니다. 그리스도를 가리키는 자리는 12절과 13절입니다.\n\n이 본문은 1054년 앞뒤에 오간 사람들의 이야기를 읽는 눈을 열어 줍니다. 그리스 수도사들 곁에 살던 라틴 수도사들과 낯선 땅을 지나간 순례자들은 서로를 전혀 모르는 사이가 아니었습니다. 이 이야기를 몸 그림에 겹쳐 읽는 것은 이 책이 택한 읽기이고, 그 시대 사람들이 그렇게 읽었다는 뜻은 아닙니다.\n\n우리와 같은 것은, 웨스트민스터 신앙고백이 그리스도 한 분을 교회의 머리로 말하고(25장 1절), 보이는 교회도 복음 아래서는 한 나라에 매이지 않는 보편 교회라고 말하는 점입니다(25장 2절). 두 줄기 교회가 그 뒤에도 같은 신경을 예배에서 읽었다는 것은 신앙고백의 말이 아니라 역사의 사실입니다. 다른 것은, 1965년의 선언이 파문을 기억에서 지웠을 뿐 차이가 풀린 것은 아니라고 밝혔고, 가톨릭과 정교회가 오늘도 완전한 교제 안에 있지 않다는 점입니다.⁷",
