            "kind": "read",
            "h": "각주",
            "t": "1. 1054년 7월 16일에 사절이 파문한 사람들(총대주교 케룰라리오스, 아크리다의 레오, 그를 따르는 이들)과 비잔티움 교회 전체나 동쪽 전체를 파문하려는 뜻은 없었다는 설명은 가톨릭 백과사전(1907~1912) 「Eastern Schism」 항목. 파문장이 제단에 놓인 일과 총대주교의 응답, 갈라짐이 여러 세대에 걸쳐 깊어졌다는 서술은 OCA, 「The Great Schism」(oca.org 교회사, 정교회 쪽 글). 1965년 12월 7일 교황 바오로 6세와 총대주교 아테나고라스 1세의 공동 선언(바티칸 영문본)은, 파문이 교회가 아니라 사람들을 겨눈 것이었고 교제를 끊으려던 것이 아니었다고 하며, 총대주교와 콘스탄티노플의 회의가 사절들에게 같은 판결을 내린 일을 적고, 교제가 실제로 끊어진 것을 그 앞뒤의 여러 일과 서로를 이해하고 믿지 못한 탓으로 돌린다.\n2. 서쪽 신경에 더해진 말을 동쪽이 문제 삼은 것은 케룰라리오스가 안티오키아의 총대주교 베드로에게 쓴 편지(Fordham 중세 자료집 영역, 「Michael Cerularius to Peter of Antioch」). 두 줄기 교회가 신경을 예배에서 읽는다는 서술은 Ware 1993.\n3. 아토스산의 아말피 수도원(980~984년 무렵 시작, 아말피와 비잔티움의 장사, 콘스탄티노플의 아말피 사람들 구역과 수도원, 필요한 물건을 그 공동체에서 받은 일, 1045년과 1081년의 황제 문서, 1087·1108·1169년의 원장 기록, 라틴 예배에 대한 반대 기록이 없다는 서술)은 Plested 2011(Speake와 Ware 편, 『아토스산: 그리스도교 동방의 작은 우주』에 실린 「Latin Monasticism on Mount Athos」).\n4. 1064~1065년의 순례(길, 예루살렘 도착, 순례의 마음)는 『알타이히 연대기』 1065년 항목(Annales Altahenses Maiores, Brundage 영역, Fordham 중세 자료집).\n5. 알렉시오스 1세의 사절과 피아첸차 회의, 클레르몽 공의회, 1098년 바리 회의는 가톨릭 백과사전(1907~1912) 「Urban II」 항목. 클레르몽 연설을 전하는 글이 판본마다 다르다는 점은 Fordham 중세 자료집의 판본 비교 자료.\n6. 케룰라리오스의 편지는 Fordham 영역(번역자의 낱말 선택일 수 있다). 풀허르가 전하는 클레르몽 연설은 Fordham 중세 자료집(Thatcher와 McNeal 1905 판 번역을 고쳐 실은 본문). 1965년 공동 선언은 바티칸 공식 영문본.\n7. 신앙고백은 웨스트민스터 신앙고백 25장 1~2절을 우리 말로 풀었다. 1965년 12월 7일의 공동 선언은 바티칸 공식 영문본. 가톨릭과 정교회가 오늘도 완전한 교제 안에 있지 않다는 설명은 OCA, 「The Great Schism」."
