            "t": "밤이 깊어도 수도사들은 일어나 기도하러 모였습니다. 서쪽 교회의 많은 수도원(수도사들이 기도하고 일하며 함께 사는 집)에서 하루는 이렇게 정해진 때마다 나뉘었습니다. 낮에는 일곱 번 모여 기도했고, 그 사이에는 손으로 일하고 거룩한 글을 읽었습니다. 이 하루의 모양을 적어 둔 것이 6세기에 베네딕투스가 쓴 『규칙』입니다.¹\n\n규칙은 수도원을 학교에 견줍니다. 주님을 섬기는 일을 배우는 곳이라는 뜻이고, 머리말은 무겁거나 거친 것을 세우려는 것이 아니라고 합니다. 끝에서는 이 규칙이 처음 걷는 사람을 위한 작은 규칙이라고 스스로 말합니다. 왜 하루에 일과 읽기를 섞었을까요? 규칙은 게으름이 영혼에 해롭기 때문이라고 말합니다.¹\n\n규칙은 하루를 엄격하게만 짜지 않았습니다. 몸이 약한 사람에게는 가벼운 일을 맡기라고 했고, 찾아온 손님은 그리스도를 맞는 마음으로 대하라고 했습니다. 이 규칙이 그리는 수도원은 기도하는 집이면서 일하는 집이고, 문을 두드리는 사람을 맞는 집이었습니다.¹\n\n그로부터 오백 년쯤 지난 11세기와 12세기에도 서쪽의 여러 수도원이 이 규칙 위에서 서로 다른 길을 찾았습니다. 클뤼니와 시토가 그 이야기입니다. 두 곳의 시작을 적은 글이 남아 있고, 이 책은 그 글을 먼저 읽습니다.\n\n클뤼니에서 자란 수도사 가운데는 로마에서 교회의 일을 맡은 사람도 있었습니다. 한 역사가는 12세기의 이 움직임을 『12세기의 개혁』이라는 이름으로 다루었습니다. 이 책은 이름을 덧붙이기보다 수도사들이 자기 하루를 어떻게 살려 했는지를 따라갑니다.²",
