            "t": "910년 무렵 아키텐의 공작 윌리엄은 아내와 함께 클뤼니라는 마을과 그 교회와 땅을 수도사들에게 내놓았습니다. 왜 그랬는지는 그때 쓴 헌장(땅을 내놓는 약속을 적은 문서)에 적혀 있습니다. 공작은 살아 있는 동안 자기 영혼의 구원을 마음에 두었습니다. 재산을 몸을 위해서만 쓰고 싶지 않았고, 세상을 버린 수도사들을 도우며 그 상을 나누고 싶어 했습니다.³\n\n헌장은 수도사들이 공작 부부와 가족, 그리고 살았거나 세상을 떠난 모든 그리스도인을 위해 기도하기로 한 것도 적었습니다. 가난한 사람과 나그네와 순례자를 힘써 돌보라는 말도 함께 있습니다. 뒷날 클뤼니 수도사들은 정해진 때의 기도에 여러 기도를 더 드렸고, 세상을 떠난 이를 위한 기도도 그 가운데 있었습니다.³ ⁴\n\n헌장은 땅을 내놓는 쪽의 약속도 적었습니다. 수도사들은 공작이나 친척이나 왕의 지배 아래 있지 않고 베네딕투스 규칙에 따라 산다고 했습니다. 첫 원장 베르노가 세상을 떠난 뒤에는 수도사들이 스스로 원장을 고른다고 했습니다. 세속의 군주도 백작도 주교도 교황도 땅을 빼앗거나 수도사들의 뜻에 어긋나게 원장을 세울 수 없다고 했고, 수도원은 로마 교황의 보호를 받는다고 했습니다. 땅을 내놓은 사람이 그 땅에 대한 자기 권한도 내려놓은 것이라고 읽을 수 있습니다.³\n\n클뤼니의 길을 따르는 수도원들은 모여 하나의 수도원 모임을 이루었습니다. 수도사 가운데는 교황이 된 이도 있습니다. 우르바누스 2세는 1070년 무렵 이곳에 들어와 뒤에 부원장(원장을 돕는 직분)이 되었습니다. 교황 그레고리우스 7세의 청으로 로마에 가서 교회를 새롭게 하는 일을 도왔습니다.⁴",
