            "t": "기도로 하루를 나누고, 손으로 일하고, 거룩한 글을 읽는 삶을 이 부름에 대한 한 가지 대답으로 읽을 수 있습니다. 다만 규칙 자체가 이 구절을 말하는 것은 아니며, 겹쳐 읽는 것은 이 책이 택한 읽기입니다.\n\n그리스도를 가리키는 자리는 11:28입니다. 쉼을 주시는 분은 수도원도 규칙도 아니고 부르시는 그리스도입니다. 클뤼니의 예배와 시토의 밭일과 베르나르두스의 글은 달라 보이지만, 모두 이 부름 앞에서 하루를 어떻게 살지 묻는 길로 읽을 수 있습니다. 쉼은 규칙을 잘 지킨 사람이 얻는 상이 아니라 부르시는 분의 약속이라고 본문은 말합니다.\n\n우리와 같은 것은, 웨스트민스터 신앙고백이 성경 읽기와 말씀 듣기와 시편 찬양을 예배의 한 부분으로 말하고(21장 5절), 날마다 가정에서 드리는 기도와 홀로 은밀히 드리는 기도도 말하는 점입니다(21장 6절). 다른 것은, 가톨릭과 정교회와 성공회에는 서약을 하고 함께 사는 수도 공동체가 있고(성공회에서는 19세기 중반에 다시 생겼습니다), 개신교 안에는 수도 공동체가 흔하지 않지만 떼제 공동체처럼 개혁교회 집안에서 시작된 곳도 있다는 점입니다. 수도 서약을 어떻게 이해하는지는 교역자와 나눕니다.⁷",
