          {
            "id": "cb02-notes",
            "kind": "read",
            "h": "각주",
            "t": "1. 베네딕투스 규칙의 머리말(주님을 섬기는 일을 익히는 학교, 무겁거나 거친 것을 세우지 않기를 바람)과 48장(손으로 하는 일과 읽기, 게으름)은 Fordham 중세 자료집의 영역을 열어 확인했다. 8장과 16장(정해진 때의 기도), 53장(손님 맞이), 73장(처음 걷는 사람을 위한 작은 규칙)은 베네딕투스 규칙의 같은 영역에서 제목과 요지를 확인했다. 6세기의 베네딕투스가 이 규칙을 썼다는 설명은 같은 자료의 설명을 따른다.\n2. Giles Constable, *The Reformation of the Twelfth Century* (Cambridge University Press, 1996). 이 책 이름이 이 시대의 움직임을 \"개혁\"이라 부른 한 학자의 선택을 보여 준다(책 내용은 열어 보지 못했다).\n3. 클뤼니 헌장(땅을 내놓은 까닭, 규칙에 따라 삶, 원장 선출, 세속의 군주와 백작과 주교와 교황의 간섭 금지, 가난한 사람과 나그네와 순례자를 돌봄, 로마의 보호, 기도)은 Henderson 1910, 329~333쪽에 실린 영역(Fordham 중세 자료집). 헌장 본문에는 연도가 없고 910년은 학계가 붙이는 연대다.\n4. 클뤼니의 수도원 모임, 뒷날 정해진 때의 기도에 더한 기도와 죽은 이를 위한 기도, 클뤼니에서 교황이 된 우르바누스 2세는 가톨릭 백과사전(1907~1912) 「Cluny」와 「Urban II」 항목.\n5. 시토의 시작(1098년, 몰렘의 로베르, 규칙을 더 엄격하게 지키려 한 뜻, 교황 사절의 허락, 공작의 도움, 수입을 받지 않는다는 규정과 평신도 형제. 이 두 가지는 영역본 15장의 규정이고 1098년 곧바로 정해진 것인지는 확인하지 못했다)은 시토 수도사들이 뒷날 자기들의 시작을 적은 『작은 시작』(Exordium Parvum)의 영역본 1~3장과 15장(학술 판본은 Waddell 1999 편). 수도사들이 정해진 기도를 지킬 수 있게 평신도 형제들이 농사를 맡았다는 설명은 가톨릭 백과사전 「Cistercians」 항목.\n6. 베르나르두스의 클레르보 설립(1115년), 『변론』의 두 부분(자신이 클뤼니를 헐뜯었다는 말의 부인과 폐단의 비판), 클뤼니 원장의 존경과 우정의 답은 가톨릭 백과사전 「St. Bernard of Clairvaux」 항목. 『변론』의 회랑 조각 비판은 Fordham 중세 자료집의 영역(Burr 번역). 『변론』의 연대(1125년 무렵)는 학자마다 몇 해씩 다르다.\n7. 신앙고백은 웨스트민스터 신앙고백 21장 5~6절을 우리 말로 풀었다. 성공회의 수도 공동체가 19세기 중반에 다시 생긴 일은 영국 성공회 누리집의 「Religious life」 쪽. 떼제 공동체는 떼제 공동체 누리집의 「History」 쪽."
          }
