            "id": "cb03-r1",
            "kind": "read",
            "h": "카노사 문 앞에서",
            "t": "1077년 1월, 독일의 왕 하인리히 4세는 이탈리아 북쪽 카노사 성의 문밖에 서 있었습니다. 겨울 알프스를 넘어 온 왕이 왕의 차림을 벗고 맨발로 사흘을 기다렸다고, 성안에 머물던 교황 그레고리우스 7세가 편지에 적었습니다.¹ 왕은 왜 거기까지 갔을까요? 이야기는 주교라는 자리에서 시작합니다.\n\n그때 서유럽의 주교와 수도원장은 예배만 맡지 않았습니다. 교회에 맡겨진 땅과 사람을 다스리는 영주이기도 했습니다. 그래서 왕들은 새 주교를 직접 골라 반지와 지팡이를 건네며 직분을 맡겼습니다(서임). 학자들은 왕이 이렇게 세운 주교를 힘센 귀족들 곁에서 나라를 꾸리는 일꾼으로 썼다고 오래 설명해 왔고, 그 설명이 얼마나 맞는지 되묻는 학자도 있습니다. 훗날의 합의문에도 새 주교가 황제에게서 땅과 그에 딸린 권한을 받고 의무를 지게 되어 있습니다.²\n\n같은 때 교회 안에서도 고쳐야 할 점을 말하는 목소리가 커졌습니다. 돈으로 교회의 직분을 사고파는 일(성직 매매)과 사제의 혼인이 문제로 꼽혔고, 1073년 교황이 된 그레고리우스 7세가 이 문제를 붙들었습니다. 그는 왕처럼 성직자가 아닌 사람에게서 직분을 받는 일도 금했습니다. 교회가 오래 지켜 온 규칙에 어긋나고 교회를 어지럽힌다는 이유였습니다.³\n\n이 책은 이 다툼을 이렇게 정리합니다. 왕에게 주교는 나라를 꾸리는 데 필요한 사람이었고, 교황에게 주교는 교회가 지켜야 할 직분이었습니다. 어느 쪽도 지키려던 것을 쉽게 내놓을 수 없었고, 결국 \"이 일은 누가 정하는가\"를 묻는 다툼이 되었습니다.",
