            "t": "마태복음 21~22장에는 예루살렘에서 여러 무리가 차례로 예수님께 질문을 가져오는 이야기가 이어지고, 이 대목은 그 가운데 하나입니다. 바리새인들은 예수님의 말씀에서 책잡을 거리를 찾으려고 의논했고, 헤롯 집안의 통치를 지지하던 사람들과 함께 자기 제자들을 보내 질문하게 했습니다(22:15~16).\n\n질문은 로마 황제에게 세금을 내는 것이 옳은가 하는 것이었습니다(22:17). 예수님은 그들의 속마음을 아시고, 세금으로 쓰는 동전을 가져오게 하십니다. 동전에 누구의 얼굴과 새겨진 글이 있는지 물으시고, 황제의 것이라는 대답을 들으십니다(22:18~21).\n\n그러고는 황제에게 돌려줄 몫과 하나님께 돌려드릴 몫이 따로 있다고 일러 주십니다. 이 말을 들은 사람들은 놀라워하며 물러갔습니다(22:21~22). 질문한 사람들은 예수님을 곤란하게 하려 했지만, 대답은 질문을 던진 이들까지 자기 자리를 돌아보게 하는 말이었습니다.",
