            "h": "본문 설명 · 황제에게 돌려줄 몫과 하나님께 돌려드릴 몫",
            "t": "이 질문은 덫이었습니다. 내라고 하면 로마의 지배를 싫어하던 사람들이 등을 돌릴 수 있었고, 내지 말라고 하면 로마가 문제 삼을 수 있었습니다. 예수님은 동전에 새겨진 글을 물으셔서 나라가 맡은 몫을 인정하시면서 하나님께 돌려드릴 몫도 말씀하십니다. 이 말씀은 두 몫의 경계를 정해 주지 않기에, 교회와 왕의 다툼 속에서도 이 물음이 다시 들렸다고 읽을 수도 있습니다.\n\n그리스도를 가리키는 자리는 이 물음에 답하신 분 자신입니다. 부활하신 그리스도는 하늘과 땅의 모든 권세를 받으셨다고 말씀하십니다(마 28:18). 교회가 지키려던 것도 왕이 지키려던 것도 그리스도의 다스리심 아래에 있다는 말씀과 이어지는 자리입니다.\n\n우리와 같은 것은, 가톨릭, 정교회, 성공회, 개신교의 교회들이 모두 마태복음을 성경으로 받고 이 말씀을 듣는다는 점입니다. 신앙고백도 나라를 맡은 사람이 말씀과 성례의 일을 대신할 수 없지만 교회의 평화를 돌볼 책임은 있다고 말합니다(23장 3절). 다른 것은 교회와 정치의 관계를 설명하는 방식입니다. 가톨릭 교회는 교회와 정치 공동체의 역할이 다르고 섞이면 안 되지만 교회가 정치의 일에도 도덕적 판단을 할 수 있다고 설명하고, 정교회의 교회사 글은 비잔티움이 교회와 나라를 서로 협력하는 관계(심포니아)로 이해했다고 설명합니다.⁸",
