            "kind": "read",
            "h": "클레르몽의 청",
            "t": "1095년 11월, 프랑스의 클레르몽에 서쪽 교회의 지도자들이 모였습니다. 이 자리에서 교황 우르바누스 2세가 동쪽의 그리스도인을 도우러 길을 떠나자고 청했습니다. 교황은 왜 동쪽을 말했을까요? 그 까닭은 몇 해를 거슬러 올라가야 보입니다.\n\n24년 전인 1071년, 동쪽 제국(비잔티움)의 황제 군대가 셀주크 군(튀르크 계통의 이슬람 세력)에게 크게 졌습니다. 클레르몽 연설을 전하는 글 가운데 몇은 그 뒤 동쪽 제국이 땅을 잃어 가고 있었다고 말합니다. 1095년에는 황제 알렉시오스 1세가 서쪽에 도움을 청했다고도 전합니다. 이 청이 교황의 결심에 얼마나 컸는지, 교황이 그날 실제로 무슨 말을 했는지는 확실하지 않습니다.¹\n\n서쪽 사람들도 동쪽 길을 이미 걷고 있었습니다. 클레르몽보다 서른 해쯤 앞서 독일 주교들이 이끈 순례단이 콘스탄티노플을 지나 예루살렘에 이르렀다고 『알타이히 연대기』가 적습니다.²\n\n이 모임의 결정으로 전해지는 글은 이렇게 적었습니다. 명예나 재물이 아니라 오직 믿음의 마음으로 예루살렘의 교회를 자유롭게 하러 가면, 그 길이 고행(죄를 뉘우치는 행위)을 대신한다는 것입니다. 그래서 순례의 길이 곧 죄를 뉘우치는 길이 되었습니다. 연대기들도 이 길을 순례로, 동쪽 형제를 돕는 일로, 죄의 용서와 이어진 일로 전합니다. 길을 떠난 사람들의 마음을 두고 학자들은 갈립니다. 믿음이 가장 컸다고 보는 이도 있고, 땅과 명예를 얻으려는 바람이 함께 있었다고 보는 이도 있습니다.³",
