            "h": "본문 설명 · 원수를 위한 기도",
            "t": "이 말씀은 원수라고 여겨지는 사람까지 마음에 품고 그를 위해 기도하라는 부름이고, 그 까닭은 우리가 얼마나 잘하는가가 아니라 하늘 아버지가 어떤 분이신가에 있습니다. 앞에서 읽은 이야기에는 서쪽 교황의 걱정과 받아들임, 동쪽 교회의 아픈 기억, 유대인 쪽의 기록이 함께 있었습니다. 이 책은 어느 쪽이 옳았는지 가리지 않고, 이 일을 여러 교회가 함께 진 짐으로 기억합니다.\n\n그리스도를 가리키는 자리는 이 말씀을 하신 분 자신입니다. 바울은 우리가 하나님께 등을 돌리고 있을 때에도 그리스도께서 우리를 대신해 죽으셨고, 그 죽음으로 우리가 하나님과 화해하게 되었다고 말합니다(롬 5:8~10). 그래서 이 말씀은 우리가 해내야 할 과제이기 전에, 그리스도께서 먼저 걸으신 길에 대한 소식입니다.\n\n우리와 같은 것은, 가톨릭, 정교회, 성공회, 개신교의 교회들이 모두 마태복음 5장을 성경으로 받고 이 말씀을 그리스도의 말씀으로 듣는다는 점입니다. 소요리문답 42문도 계명 전체를 하나님을 사랑하고 이웃을 내 몸처럼 사랑하는 것으로 간추립니다. 다른 것은 이 일을 전하고 기억하는 방식입니다. 중세의 글들은 클레르몽의 청을 순례와 죄의 용서, 동방 교회를 돕는 일과 이어 전했고, 2001년 교황은 정교회 형제자매에게 지은 잘못을 두고 주님께 용서를 구했으며, 정교회는 1204년을 같은 그리스도인의 도시가 입은 아픔으로 기억합니다.⁸",
