            "h": "스승 곁에 모인 학생들",
            "t": "12세기에 이름난 스승을 찾아 고향을 떠난 젊은 학생 한 사람을 그려 봅니다. 어렵게 파리나 볼로냐에 닿았지만, 이 도시에서 그는 시민이 아닙니다. 방을 구하기도 어려웠고, 다툼이 생겨도 기댈 곳이 없었습니다. 집세도 문제여서 뒷날 볼로냐에서는 집값을 학생 쪽 둘, 시민 쪽 둘이 정하는 방법까지 생겼습니다. 그런 학생이 한둘이 아니었고, 낯선 도시에서 혼자서는 힘이 약했습니다.\n\n그래서 학생들은 서로를 지킬 모임을 만들었습니다. 볼로냐에서는 고향을 떠나온 학생들이 조합(같은 처지의 사람들이 서로 돕고 규칙을 정하려고 세운 모임)을 이루었다고 설명합니다. 이 조합은 맹세로 서로를 묶어 힘을 얻었다고 합니다. 1158년에는 황제가 공부하러 떠도는 학생들이 비열한 이들에게 부당한 일을 자주 겪는다고 보았습니다. 그래서 법을 배우는 곳에서 이들이 안전하게 지내고 스승이나 주교 앞에서 재판받을 길을 열어 주는 법을 내렸습니다.¹\n\n파리는 다른 길로 자랐습니다. 11세기 끝 무렵부터 이름난 스승들이 대성당 곁 학교에서 가르치며 배움의 중심이 되었고, 가르칠 자격을 받은 스승들이 하나의 모임을 이루었습니다. 이 모임이 12세기 끝 무렵에 대학이라 부를 모양을 갖추었다고 보지만, 그 시기는 학자마다 다르게 봅니다. 1200년에는 학생과 시민 사이의 싸움 뒤에 왕이 학생을 보호하는 조치를 내렸습니다. 이렇게 대학은 스승과 학생이 서로를 지키고 배움을 스스로 다스리려고 모인 단체로 자랐습니다.²\n\n아래 표는 세 곳의 이름난 공부와 알려진 때를 한눈에 보는 참고입니다.\n\n| 곳 | 이름난 공부와 알려진 때 |\n| --- | --- |\n| 파리 | 신학, 교양 학문(논리 같은 기초 과목). 12세기 끝 무렵 |\n| 볼로냐 | 법. 1158년 황제의 보호법 |\n| 옥스퍼드 | 1096년에 이미 가르침이 있었고 1167년 뒤 빠르게 자람(옥스퍼드대학의 설명) |",
