          {
            "id": "cb05-r2",
            "kind": "read",
            "h": "믿음이 이해를 찾는다",
            "t": "시간을 조금 거슬러 올라가 봅니다. 대학이 모양을 갖추기 앞서도 수도원 안에서는 배움이 깊어지고 있었습니다. 안셀무스는 이탈리아 북쪽에서 태어나 노르망디의 베크 수도원에서 수도사로 살았고, 뒷날 캔터베리 대주교가 되었습니다. 수도사의 하루는 기도와 성경 읽기로 채워졌습니다.³\n\n그는 먼저 여든 장에 걸쳐 논증(이유를 들어 보이는 일)을 하나씩 쌓아 가는 긴 글을 썼습니다. 그러고는 이 많은 논증 대신 한 가지 논증만으로 하나님이 계시다는 것과 하나님이 어떤 분이신지를 보이고 싶어 했습니다. 그 논증은 잡힐 듯하다가도 사라지기를 되풀이했습니다. 그는 거의 포기하려 했지만, 밀어낼수록 생각이 더 따라붙었다고 서문에 적었습니다. 그러다 어느 날 그토록 찾던 것을 찾았다고 합니다.³\n\n1077~1078년 무렵 이렇게 나온 글이 『프로슬로기온』입니다. 이 글은 해설이 아니라 기도처럼 시작합니다. 안셀무스는 하나님이 가르쳐 주셔야 그분을 찾을 수 있다고 구합니다. 그리고 이해하고 나서 믿으려는 것이 아니라 믿기 때문에 이해하려 한다고 말합니다. 이 글에 처음 붙인 이름도 \"이해를 찾는 믿음\"이었습니다.³\n\n찾아낸 논증은 하나님을 그보다 더 큰 것을 생각할 수 없는 분으로 이해하는 데서 출발합니다. 연구자들은 안셀무스의 믿음을 하나님을 사랑하는 마음으로 읽고, 이해는 그 사랑이 사랑하는 분을 더 알려고 나아가는 일이라고 봅니다. 그러면서도 그는 이 글이 하나님이 없다고 말하는 사람까지 설득하기를 바랐다고 합니다. 믿음을 버리고 이성으로 건너가자는 뜻은 아니었습니다.³"
          },
          {
            "id": "cb05-r3",
            "kind": "read",
            "h": "질문을 세우는 공부",
            "t": "12세기 전반, 파리의 스승 아벨라르는 『긍정과 부정』이라는 책을 엮었습니다. 교부(초기 교회의 스승들)의 글에서 서로 어긋나 보이는 말을 질문마다 모아 찬성과 반대를 나란히 놓은 책입니다. 교부들이 같은 낱말을 다르게 쓰거나 말한 자리가 달라서 부딪쳐 보일 수 있으니, 낱말의 뜻과 말한 자리를 살피라고 서문은 일러 줍니다. 그러나 답은 정해 주지 않습니다. 젊은 독자들이 스스로 물으며 진리를 찾도록 깨우치려는 뜻이었고, 묻고 따지다 보면 진리에 가까이 간다고 그는 믿었습니다.⁴\n\n모두가 이 길을 반긴 것은 아닙니다. 1140년 무렵 상스에서 열린 회의는 아벨라르의 글에서 주장 몇 가지를 가려 잘못되었다고 판단했고, 교황도 이를 확인해 그에게 침묵을 명했습니다. 수도원장 베르나르두스는 믿음의 일을 논증으로 다루는 방식을 걱정했다고 전합니다. 한쪽은 묻는 일을, 다른 쪽은 믿음을 조심스럽게 다루는 일을 지키려 했습니다. 아벨라르는 뒤에 보호를 받으며 세상을 떠났고, 교황은 그 처분을 풀었습니다.⁴\n\n한 세기 남짓 뒤, 아퀴나스가 파리 대학에서 가르치던 때에는 아리스토텔레스의 글이 새로 번역되어 학교로 들어와 있었습니다. 처음에는 교회 안에 이 글을 막으려는 움직임도 있었지만 차츰 학교의 공부로 자리 잡았습니다. 아퀴나스는 이 새 물음들을 믿음의 가르침과 이어, 처음 배우는 이들이 따라올 수 있도록 『신학대전』을 썼다고 서문에서 밝힙니다. 항목마다 질문을 세우고, 반대하는 말을 먼저 들고, 자기 답을 한 뒤, 반대 말 하나하나에 답하는 이 순서는 강의실의 토론을 닮았습니다.⁵\n\n이렇게 질문하고 이유를 들어 따지며 믿음을 이해하려는 학교의 공부를 스콜라 신학이라 부릅니다. 무엇을 지키려는 질문이었는지는 이야기하는 이마다 다르게 읽습니다. 교회마다 아퀴나스와 스콜라 신학을 평가해 온 방식도 같지 않으며, 이것은 아래 본문 설명에서 다시 만납니다.\n\n아래 표는 두 책이 질문을 다루는 순서를 한눈에 보는 참고입니다.⁵\n\n| 순서 | 『긍정과 부정』(아벨라르, 12세기 전반) | 『신학대전』의 한 항목(아퀴나스, 13세기) |\n| --- | --- | --- |\n| 1. 질문을 세운다 | 어긋나 보이는 교부들의 말을 질문 하나로 묶는다 | 항목 제목을 \"…인가?\"라는 물음으로 세운다 |\n| 2. 앞선 말을 모은다 | 찬성하는 말과 반대하는 말을 나란히 놓는다 | 먼저 그렇지 않다고 보는 견해들을 든다 |\n| 3. 따져 본다 | 낱말의 뜻과 말한 자리를 살피라고 일러 준다 | 성경이나 교부의 말을 들고 \"내가 답한다\"에서 이유를 밝힌다 |\n| 4. 답한다 | 답을 정하지 않고 읽는 이에게 맡긴다 | 처음의 견해마다 하나씩 답한다 |"
          }
