            "t": "카스티야 출신의 도미니쿠스는 대성당의 참사회원(성당에서 함께 기도하며 사는 사제)이었습니다. 수도회의 초기 기록은, 그가 주교 디에고와 함께 남프랑스를 지나며 공식 가르침과 다른 믿음이 퍼진 땅을 보았다고 전합니다. 그곳에서 일하던 교황의 사절들은 부유한 모습으로 다녔습니다. 디에고는 그런 모습이 말씀의 힘을 깎는다고 보았습니다. 그래서 가난하고 낮은 모습으로 걸어 다니며 설교하자고 했고, 도미니쿠스도 이 길에 함께했습니다.⁵\n\n1215년 그 지방 주교가 도미니쿠스의 모임을 교회의 모임으로 세웠습니다. 같은 해 공의회는 새 수도회를 세우지 못하게 했습니다. 그래서 형제들은 새 규칙을 만들지 않고 아우구스티누스 규칙(옛 시대부터 쓰인 수도 규칙)을 받아, 새 일을 하는 모임으로 시작했습니다. 1216년 12월 교황이 이 모임을 허락했습니다.⁵\n\n1217년 8월 도미니쿠스는 따르는 이들을 여러 곳으로 보냈고, 그 가운데에는 파리와 볼로냐 같은 대학 도시가 있었습니다. 도미니쿠스는 대학에서 공부한 사람이었습니다. 설교가 힘을 가지려면 배움이 있어야 한다고 보아 형제들에게 좋은 가르침을 받게 하려 했다고 『가톨릭 백과사전』은 설명합니다. 도미니쿠스는 1221년에 세상을 떠났지만 형제들의 모임은 이어졌습니다.⁵\n\n프란체스코의 형제들과 도미니쿠스의 형제들은 도시에서 말씀을 전하려고 일어났다는 점이 닮았습니다. 시작한 곳과 규칙과 일하는 모양은 다릅니다. 그래도 두 모임 모두 교황의 허락을 받은 모임이 되었습니다.\n\n아래 표는 두 모임이 시작하고 자란 길을 나란히 놓은 참고입니다.⁶\n\n| 항목 | 프란체스코의 형제들(작은 형제들) | 도미니쿠스의 형제들(설교자들) |\n| --- | --- | --- |\n| 시작 | 이탈리아 아시시, 13세기 첫 십 년 무렵 | 남프랑스, 1215년 |\n| 교황과의 관계 | 첫 규칙 제출 1209년 무렵, 『규칙』 확인 1223년 | 1216년 12월 허락(인가) |\n| 규칙의 바탕 | 프란체스코의 『규칙』 | 아우구스티누스 규칙 |\n| 삶의 모양 | 돈을 받지 않고 일하며 필요할 때 도움을 구함. 도시를 오가며 설교 | 소유 없이 설교하며 걸식으로 지냄(1220년 첫 총회 이후). 대학 도시에서 공부와 설교 |\n| 오늘 | 가톨릭 교회 안에서 이어짐. 성공회에도 프란체스코의 이름을 딴 수도 공동체가 있음 | 가톨릭 교회 안에서 이어짐 |"
