            "t": "이 과는 동쪽 교회(정교회)가 믿음을 사람들이 알아듣는 말로 이어 간 세 장면을 읽습니다. 슬라브 사람들의 글자, 키예프의 세례, 수도사의 짧은 기도입니다.\n\n9세기 중반, 중부 유럽의 모라비아라는 나라에서 로스티슬라프 공(왕과 같은 나라의 우두머리)이 동쪽 제국의 황제에게 사람을 보냈습니다. 백성이 옛 믿음을 버리고 그리스도인의 길을 걷는데, 자기들 말로 믿음을 풀어 줄 선생이 없다는 것이었습니다.¹ 그 땅에서는 서쪽의 프랑크 사제들이 라틴어로 가르치고 있었습니다. 공에게는 프랑크 왕국에 맞서 동쪽 제국과 손잡으려는 뜻도 있었다고 정교회는 설명합니다.²\n\n황제는 형제를 보냈습니다. 그리스 도시에서 자라 슬라브 말을 익힌 키릴로스와 메토디우스였습니다. 글자가 없으면 성경을 적어 둘 수 없으니, 키릴로스는 먼저 슬라브 말의 글자가 있어야 한다고 보았습니다. 그는 863년 모라비아에 닿기 전 글자를 만들었습니다. 그리고 복음서와 예배서를 슬라브 말로 옮기고, 글을 가르치고, 슬라브 사람 사제들을 길렀습니다.²\n\n반대하는 이들도 있었습니다. 하나님을 찬양할 수 있는 말은 라틴어와 그리스어와 히브리어뿐이라는 주장이었습니다. 키릴로스의 전기는 그가 하나님의 비와 해가 모든 민족에게 닿는다고 답했다고 전합니다. 자기 글자를 가진 민족이 이미 여럿이라는 말도 했다고 합니다. 형제가 로마에 가자 교황은 슬라브 말 예배서를 받아들였습니다.¹ ³\n\n가톨릭도 이 형제를 기립니다. 1980년 교황 요한 바오로 2세는 두 사람을 유럽의 공동 수호성인으로 선포했습니다. 5년 뒤의 회칙에서는 형제가 슬라브 말로 예배한 일을 높이 평가했습니다.³",
