            "h": "키예프의 세례와 몽골의 시대",
            "t": "형제가 글자를 만든 때로부터 125년쯤 뒤인 988년 무렵, 키예프(오늘의 키이우)의 블라디미르 공이 세례를 받았습니다. 공은 옛 신들을 섬기던 사람이었습니다. 『루스 원초 연대기』는 공이 이웃 나라들의 믿음을 알아보려고 사절을 보냈다고 전합니다. 사절들은 이웃 나라들의 예배를 차례로 보았고, 콘스탄티노플의 예배에서는 하늘인지 땅인지 모를 만큼 놀랐다고 보고했습니다. 이것은 키예프 사람이 남긴 이야기입니다. 이 연대기는 사건보다 한 세기 남짓 뒤에 엮여 전설이 섞여 있으니, 그렇게 보고 읽어야 합니다.⁴\n\n연대기에 따르면 공의 신하들은 할머니 올가가 이미 이 믿음을 받아들였다는 점을 짚었습니다. 또 공은 동쪽 황제의 누이와 혼인하려 했고, 황제들은 먼저 세례를 받으라고 요구했습니다. 그러니 믿음에 대한 마음과 두 나라 사이의 사정이 함께 있던 일이었습니다. 키예프 사람들도 강에서 세례를 받았습니다.⁴\n\n1240년 몽골군이 키예프를 점령해 루스의 땅은 몽골의 지배 아래 들어갔습니다. 도시가 크게 무너지고 이웃의 모스크바가 자라자, 교회 지도자의 자리도 1325년 모스크바로 옮겨 갔다고 정교회는 설명합니다. 그 시대 수도사 세르기가 세운 공동체에서는 제자들이 서른 곳 가까운 수도원을 세웠다고 전합니다.⁵\n\n이 과는 동쪽 교회 가운데 정교회의 길을 따라갑니다. 아르메니아, 시리아, 이집트, 에티오피아의 교회들도 저마다의 길을 걸었습니다. 아래 표는 이 카드의 때를 한눈에 보는 참고입니다.\n\n| 때 | 곳 | 일 |\n| --- | --- | --- |\n| 863년 무렵 | 모라비아 | 형제가 슬라브 말 글자를 만들고 복음서와 예배서를 옮김 |\n| 988년 무렵 | 키예프 | 블라디미르 공의 세례 |\n| 1240년 | 키예프 | 몽골군이 도시를 점령함 |\n| 1325년 | 모스크바 | 교회 지도자의 자리가 옮겨 감(정교회의 설명) |"
