            "t": "1204년 십자군에게 점령된 콘스탄티노플에는 라틴 제국이 섰고, 비잔티움의 교회와 황실은 니케아 같은 곳에서 이어졌습니다. 1261년 미카엘 8세 팔라이올로고스가 도시를 되찾았습니다. 황제는 서쪽에서 올 군사의 위협을 걱정했고, 교황 그레고리우스 10세가 공의회를 청했을 때 편지를 가진 사절단을 보내 응했다고 정교회는 전합니다.¹\n\n리옹의 공의회는 1054년 이후 이백 년 넘게 지난 때에 열렸습니다. 이 과는 리옹(1274)과 피렌체(1439)의 두 합의가 어떻게 맺어졌고 그 뒤 어떻게 되었는지를 차례로 따라갑니다. 합의에 서명한 쪽과 받아들이지 않은 쪽은 하나가 되는 길을 두고 생각이 달랐고, 그 생각은 오늘의 설명에도 이어져 있습니다.\n\n서쪽은 이 합의들을 교회를 하나로 모으는 길이었다고 설명하고, 동쪽 사람들은 도시를 지키려는 황제의 사정이 컸고 합의를 교회 전체가 받아들이지 않았다고 설명합니다.² 아래 이야기는 두 설명을 나란히 읽어 갑니다.",
