            "h": "피렌체 1439, 그리고 1453년",
            "t": "1438년부터 1439년까지 페라라와 피렌체에서 열린 공의회에 교황 에우제니우스 4세와 황제 요한 8세 팔라이올로고스, 동쪽 교회의 대표들이 모였습니다. 교황의 칙서는 그리스 사람과 라틴 사람이 하나가 되는 말에 뜻을 모았다고 기록합니다. 1439년 7월 6일 합의문 『라에텐투르 카일리』가 선포되었고, 에베소의 마르코스는 서명하지 않았다고 전합니다.⁵\n\n이 합의는 동쪽 교회에서 널리 받아들여지지 않았고, 교회 안의 의견은 끝내 모이지 않았다고 전합니다. 1452년 12월 하기아 소피아에서 피렌체의 합의가 선포되었지만, 이듬해 5월 29일 콘스탄티노플은 오스만 군에게 함락되었습니다.⁵\n\n오스만의 땅에서 이어진 뒷이야기도 있습니다. 1484년 무렵 콘스탄티노플에서 열린 회의는 피렌체의 합의를 무효로 한다고 정했습니다.⁶ 합의의 시도와 그 뒤의 일은 이렇게 두 세기 남짓에 걸쳐 이어졌습니다. 이 과에서 만난 합의의 시도들을 사실만 표로 모으면 아래와 같습니다.\n\n| 해 | 곳 | 일 | 그 뒤 |\n| --- | --- | --- | --- |\n| 1274년 | 리옹(프랑스) | 교황 그레고리우스 10세의 공의회에 황제 미카엘 8세의 사절단이 와서, 동쪽이 교황의 으뜸 자리와 서쪽의 신앙의 말을 받아들이고 동쪽의 예식과 관습은 지키기로 함 | 콘스탄티노플에서 반대가 컸고 1282년 합의를 거두어들임 |\n| 1439년 | 페라라와 피렌체(이탈리아) | 교황 에우제니우스 4세가 황제 요한 8세 팔라이올로고스와 합의해 7월 6일 합의문 『라에텐투르 카일리』를 선포함. 에베소의 마르코스는 서명하지 않았다고 전함 | 동쪽 교회에서 널리 받아들여지지 않음 |\n| 1452년 | 콘스탄티노플 하기아 소피아 | 12월 피렌체의 합의가 선포됨 | 이듬해 5월 29일 도시가 오스만 군에게 함락됨 |\n| 1484년 무렵 | 콘스탄티노플 | 회의가 피렌체의 합의를 무효로 한다고 정함 | 동쪽 교회가 피렌체의 합의를 받아들이지 않았다는 기록으로 남음 |"
