            "t": "시편 133편이 노래하는 것은 형제가 함께 사는 모습입니다. 리옹과 피렌체의 합의에 서명한 쪽과 받아들이지 않은 쪽은 하나가 되는 길을 두고 생각이 달랐고, 이 이야기는 그 다름을 사실대로 보여 줍니다.\n\n이 노래에서 그리스도를 가리키는 자리는 신약이 하나 됨을 한 몸, 한 성령, 한 주님 안의 일로 이어 읽는 곳입니다(엡 4:3~6). 시편의 노래는 한 몸으로 불린 사람들의 하나 됨을 가리키고, 그 하나 됨은 이미 그리스도 안에서 주어진 것으로 읽힙니다.\n\n우리와 같은 것은 네 교회가 함께 받아 온 니케아-콘스탄티노플 신경이 한 거룩한 공교회를 고백하고, 에베소서 4:4~6의 한 몸, 한 성령, 한 주님을 함께 읽는다는 것입니다. 다른 것은 하나 됨을 이루는 길입니다. 서쪽은 공의회의 합의와 교황의 으뜸 자리 안에서, 동쪽은 교회 전체가 받아들이는 공의회의 길 안에서 하나 됨을 찾으려 했다고 각각 설명하고, 개혁교회는 뒷날의 고백에서 보이는 교회를 세상 모든 곳에서 참된 종교를 고백하는 이들로 말하며(25장 2절) 사도 시대 뒤의 회의는 오류를 범할 수 있지만 신앙과 삶에 도움이 된다고 말해 왔습니다(31장 4절).⁷",
