            "t": "중세 서쪽의 보통 사람에게 교회는 먼저 마을의 성당(사제 한 사람이 돌보는 지역의 성당, 교구 성당)이었습니다. 사람들은 일요일마다 그곳에 모여 미사(빵과 포도주를 나누는 성찬을 중심으로 드리는 예배)에 참여했고, 한 해는 부활절을 중심으로 사순절(부활절을 앞두고 갖는 준비 기간)의 금식과 참회, 부활의 기쁨, 성인을 기리는 날들로 짜여 있었습니다. 정교회도 자기 교회력이 부활절(파스카)을 중심으로 금식 기간과 성모를 기리는 날들을 품고 있다고 설명합니다.\n\n1215년 제4차 라테란 공의회는 분별할 나이가 된 모든 신자가 해마다 한 번은 자기 교구 사제에게 죄를 고백하고(고해), 적어도 부활절에는 성찬을 받으라고 정했습니다. 이 결정은 서쪽 교회 신자들의 신앙생활을 짜는 데 오래 영향을 주었다고 학자들은 설명합니다.¹\n\n마을에는 성당과 함께 이웃을 돌보는 모임도 있었습니다. 잉글랜드의 일부 교구에는 형제회(함께 기도하고 서로 돕는 신자들의 모임)가 있었다고 학자들은 설명합니다.² 순례와 성인의 날도 신자들이 한 해를 신앙으로 채우는 길이었습니다. 아래 표는 한 해와 이웃 생활을 한눈에 정리한 것입니다. 때와 모양은 지역마다 달랐습니다.\n\n| 때 | 하는 일 | 알아 둘 것 |\n| --- | --- | --- |\n| 일요일마다 | 마을 성당에 모여 미사에 참여하고 말씀을 들음 | 가톨릭은 일요일을 부활을 기억하는 주님의 날로 설명함 |\n| 사순절 | 금식과 참회로 부활절을 준비함 | 가톨릭은 부활절을 한 해의 중심으로 설명함 |\n| 부활절 무렵 | 해마다 고해와 성찬을 함 | 1215년 제4차 라테란 공의회가 정함 |\n| 성인의 날 | 달력에 적힌 순교자와 성인을 기억함 | 성인의 이야기가 책으로 엮여 읽힘 |\n| 순례 | 성당이나 성지를 찾아 걸음 | 로마, 예루살렘, 산티아고 같은 곳이 이름났음 |\n| 형제회 모임 | 함께 기도하고 서로 도움 | 잉글랜드의 일부 교구에서 볼 수 있음 |",
