            "t": "순례는 성지나 성인을 기리는 곳까지 걸어가는 신앙의 길이었습니다. 로마와 예루살렘, 에스파냐의 산티아고, 잉글랜드의 캔터베리 같은 곳이 이름난 순례지였고, 사람들은 여러 마음을 품고 길을 나섰다고 학자들은 설명합니다.\n\n달력의 날마다 기억하는 성인이 있었습니다. 도미니쿠스회 수사 야코부스가 1260년대 무렵 성인들의 이야기를 달력 순서로 엮은 『황금 전설』은 중세에 인기를 끈 책이었습니다. 전설이 섞인 책이라 모든 이야기가 역사 기록은 아닙니다. 한편 1384년 헤이르트 흐로터가 세상을 떠난 뒤 공동생활 형제단과 근대 경건 운동이 자랐고, 이 흐름 속에서 그리스도를 본받는 삶을 권하는 책으로 알려진 『그리스도를 본받아』가 읽혔습니다.³\n\n가톨릭 교리서는 교회가 성인을 기리는 날에 그들이 그리스도의 고난과 영광에 함께한 사람이며 믿는 이들의 본보기라고 설명하고, 성모는 특별한 사랑으로 기린다고 말합니다. 정교회는 성모(테오토코스, 하나님을 낳으신 분)의 탄생, 성전 입당, 수태고지, 잠드심의 날을 큰 절기로 지킨다고 설명합니다.⁴ 이 날들을 기리는 일이 어떤 뜻인지에 관한 신학 논의는 이 책이 다루지 않고, 두 교회가 자기를 어떻게 설명하는지만 적습니다."
