            "t": "가톨릭교회 교리서는 하나님의 은총 안에서 죽었지만 아직 온전히 깨끗해지지 못한 사람이 하늘에 들어가기 위해 죽은 뒤에 정화를 받는다고 설명하고, 이것을 연옥이라 부릅니다. 이 가르침은 죽은 이를 위해 기도하고 성찬을 드려 온 교회의 오랜 습관에 기댄다고 합니다. 가톨릭은 용서받은 뒤에도 남는 죄의 영향(교리서는 '잠벌'이라 부릅니다)을 교회가 그리스도와 성인들의 공로의 보고(쌓아 둔 은혜의 창고)에서 덜어 주는 일을 대사라고 부르고, 그 증서를 흔히 면죄부라 불렀습니다.\n\n이 설명이 중세에 자란 길은 아래 표와 같습니다. 연옥의 가르침이 12세기 무렵 자리를 잡았다고 읽는 학자가 있고, 그 뿌리를 훨씬 앞 시대에서 찾는 학자도 있어 의견이 갈립니다. 교회 안에서도 걱정하는 목소리가 있었습니다. 1215년 라테란 공의회는 분별없이 주는 대사가 교회의 권위를 가볍게 하고 참회의 기강을 약하게 한다고 걱정했습니다.⁵\n\n| 때 | 일 |\n| --- | --- |\n| 교회 초기부터 | 죽은 이를 위해 기도하고 성찬을 드려 온 교회의 습관(가톨릭의 설명) |\n| 12세기 | 연옥의 가르침이 이 무렵 자랐다고 읽는 학자와 더 이른 뿌리를 찾는 학자가 있어 갈림 |\n| 1215년 | 제4차 라테란 공의회가 교회가 주는 대사의 기간에 한도를 정함 |\n| 1343년 | 클레멘스 6세의 칙서 『우니게니투스』가 대사와 그리스도와 성인들의 공로의 보고를 이어 설명함 |\n| 뒷날 | 가톨릭 교리서는 연옥의 가르침이 피렌체 공의회와 트렌토 공의회에서 정리되었다고 설명함 |\n\n뒷날 개혁교회의 웨스트민스터 신앙고백(1647)은 믿는 이의 영혼이 죽은 뒤 곧 가장 높은 하늘에 받아들여진다고 하고(32장 1절), 죽은 이를 위해서는 기도하지 않는다고 말합니다(21장 4절).⁶ 이 책은 어느 쪽이 옳은지 판정하지 않고 두 설명을 나란히 놓습니다."
