            "t": "베뢰아 사람들이 칭찬받은 것은 의심이 많아서가 아니라 열린 마음으로 들으며 성경에서 확인했기 때문입니다. 17:11은 확인한 내용을 적지 않지만, 앞서 바울이 전한 소식, 곧 고난을 받으시고 죽음에서 일어나신 그리스도의 소식이었을 것입니다(17:2~3). 그리스도를 가리키는 자리는 이 소식입니다.\n\n이 이야기는 성경을 보통 사람의 말로 읽으려던 때와 만납니다. 성경을 여러 나라 말로 옮기고 설교한 사람들은 들은 말을 사람들이 직접 성경에서 확인하기를 바랐고, 번역과 읽기에 허가를 둔 쪽은 잘못된 가르침이 퍼질까 걱정했습니다.\n\n우리와 같은 것, 다른 것. 웨스트민스터 신앙고백 1장 8절은 성경이 모든 민족의 말로 옮겨져야 하고, 하나님의 백성이 성경을 읽고 살필 권리와 명령이 있다고 말합니다. 다른 것은 교회마다 성경을 읽고 옮기는 일을 설명해 온 방식이 다르다는 점입니다. 중세 서쪽 교회는 라틴어 성경을 예배와 학교의 성경으로 두었고, 지역에 따라 속인의 읽기와 번역에 허가를 두었습니다. 오늘 가톨릭교회는 모든 신자가 성경에 쉽게 다가갈 수 있어야 하고 여러 나라 말 번역을 마련해야 한다고 말합니다.⁷ 왈도, 위클리프, 후스를 기억하는 방식도 교회마다 다르고, '종교개혁의 샛별'이라는 이름은 뒷날 붙은 말입니다.",
