            "t": "14세기가 시작될 무렵 로마의 주교인 교황 보니파시우스 8세는 프랑스 왕 필리프 4세와 부딪혔습니다. 1302년 교황은 칙서(교황이 공식으로 내는 문서) 『우남 상탐』에서 교회는 하나이고 교황이 그 으뜸이라고 설명했고, 왕은 왕국 안의 일은 왕이 맡는다는 입장이었습니다.¹ 이듬해 아나니에서 교황이 왕의 사람들에게 붙잡혀 모욕을 당했다가 풀려났고, 얼마 뒤 세상을 떠났습니다.\n\n1309년부터 1377년까지 교황청은 로마가 아니라 프랑스 남쪽 도시 아비뇽에 있었습니다. 교황 클레멘스 5세를 비롯해 일곱 교황이 차례로 그곳에서 교회를 돌보았습니다. 그 사이 우르바누스 5세는 1367년부터 1370년까지 로마에 머물기도 했습니다.\n\n시에나의 카테리나(1347~1380)는 교황에게 편지를 보낸 사람이었습니다. 카테리나는 1376년 무렵 아비뇽을 찾아가고 편지로도 그레고리우스 11세에게 로마로 돌아오기를 권했습니다. 1377년 교황 그레고리우스 11세는 교황청을 로마로 옮겼습니다.",
