            "t": "1409년 피사 공의회(교회 지도자들이 모여 중요한 일을 정하는 큰 모임)가 두 교황과 별도로 세 번째 교황 알렉산데르 5세를 세웠고, 그래서 교황이 셋이 되었습니다. 이 일을 풀기 위해 1414년부터 1418년까지 콘스탄츠에서 다시 공의회가 열렸습니다.\n\n공의회는 1415년 4월 다섯째 회기에서 『하이크 상크타』(이 거룩한 공의회라는 뜻의 첫머리 말)를 정했습니다. 공의회가 그리스도에게서 직접 권한을 받았으므로 믿음과 분열을 끝내는 일과 교회의 개혁에 관해서는 교황도 따라야 한다는 글입니다.³ 1415년 그레고리우스 12세가 물러나고 요한 23세가 폐위되었으며, 1417년 베네딕투스 13세가 폐위된 뒤 그해 11월 마르티누스 5세가 뽑혀 분열이 끝났습니다. 같은 공의회에서 후스도 재판을 받았습니다.\n\n공의회는 앞으로 정해진 때마다 다시 모이기로 하는 결정(『프레쿠엔스』, 1417)도 내렸습니다. 공의회와 교황의 권한을 어떻게 이해할 것인가에 대해서는 여러 설명이 나란히 이어져 왔습니다. 아래 표는 교회들이 자기를 설명한 말과 콘스탄츠에서 나온 읽기를 나란히 둔 것으로, 어느 쪽이 옳은지는 가리지 않습니다.\n\n| 이해하는 방식 | 공의회와 교황의 권한 | 지키려는 것 |\n| --- | --- | --- |\n| 정교회의 설명 | 정교회는 공의회의 결정을 주교들이 내리고, 그 결정을 교회 전체가 받아들일 때 일반 공의회로 여겨진다고 설명한다⁴ | 교회 전체가 한 몸으로 믿음을 받아 지키는 모습 |\n| 가톨릭의 설명 | 가톨릭은 교황과 주교단이 한 몸이며, 주교단은 머리인 교황과 함께할 때 교회 전체에 대한 최고 권한을 가지고, 공의회는 교황의 확인이 있어야 유효하다고 설명한다(교리서 880~885항)⁵ | 보이는 한 자리에서 교회의 하나됨을 지키는 일 |\n| 콘스탄츠에서 나온 읽기 | 『하이크 상크타』는 분열을 끝내고 교회를 개혁하는 일에서 교황도 공의회를 따라야 한다고 정했다. 이 결정의 효력에 대한 평가는 학자마다 갈린다 | 교황이 둘 셋일 때 교회가 스스로 하나를 되찾을 길 |"
