            "t": "1450년대 중반 독일 마인츠에서 구텐베르크가 금속 낱글자를 짜 맞추는 활자로 성경을 찍었습니다. 이 성경은 교회가 예배와 학교에서 써 온 라틴어 성경(불가타)이었습니다. 손으로 베끼던 때보다 같은 책을 여러 권 만들기가 쉬워졌고, 인쇄소가 있는 도시는 15세기 안에 늘어 갔습니다.\n\n책이 퍼지는 길은 라틴어 성경만이 아니었습니다. 성경의 일부는 인쇄 이전에도 여러 나라 말로 옮겨져 읽혀 왔고, 15세기 후반에는 여러 나라 말 성경이 인쇄로 나왔습니다. 읽을 수 있는 사람과 책을 가질 수 있는 사람이 이전보다 넓어질 길이 열린 때였습니다.\n\n인쇄가 교회와 사회를 얼마나 바꾸었는지는 학자마다 갈립니다. 인쇄를 큰 변화의 일꾼으로 보는 읽기가 있고, 처음 수십 년의 인쇄는 돈이 많이 들고 읽는 사람도 한정되어 변화가 더뎠다고 보는 읽기가 있습니다.³ 이 책은 어느 쪽도 정하지 않고, 책이 퍼지는 길이 열렸다는 사실만 기억합니다.\n\n| 때 | 일 |\n| --- | --- |\n| 1440년 | 발라가 『콘스탄티누스의 기증』이 뒤에 지어진 글임을 보임 |\n| 1450년대 중반 | 구텐베르크가 마인츠에서 성경을 인쇄함 |\n| 15세기 후반 | 여러 나라 말 성경이 인쇄로 나오고 인쇄소 도시가 늘어남 |\n| 1512년 | 제5차 라테란 공의회가 시작됨 |\n| 1515년 | 새 책을 찍기 전에 교회의 검토를 받게 하는 결정이 전해짐 |\n| 1516년 | 에라스뮈스가 그리스어 신약 성경을 인쇄함 |\n| 1517년 3월 | 제5차 라테란 공의회가 끝남 |",
