            "t": "느헤미야 8장은 예루살렘 성벽이 다시 세워진 뒤의 이야기입니다. 온 백성이 하나로 모여 물의 문 앞 넓은 마당에 섰고, 서기관 에스라에게 하나님의 율법 책을 가져오라고 청했습니다. 성벽 공사를 마친 사람들이 이번에는 말씀 앞에 모인 것입니다.\n\n한 해의 일곱째 달 첫날, 에스라는 남자와 여자, 들어서 알아들을 나이가 된 사람들 앞에 책을 가져왔습니다. 한 사람이 아니라 온 백성의 모임이었습니다. 그는 새벽부터 한낮이 되도록 마당을 향해 책을 읽었고, 사람들은 모두 귀를 기울였습니다.\n\n에스라는 이 일을 위해 만든 나무 연단 위에서 모두가 보는 앞에 책을 폈고, 사람들은 일어섰습니다. 에스라가 하나님을 찬양하자 사람들은 두 손을 들고 아멘으로 답하며 엎드려 경배했습니다. 레위 사람들은 읽는 말을 사람들이 알아듣도록 도왔고, 책은 또렷하게 읽히며 그 뜻이 풀렸습니다. 읽는 소리와 풀이하는 말이 함께 모임을 채웠습니다.",
