            "t": "느헤미야 8장의 모임에는 책을 읽는 사람과, 읽은 말을 알아듣도록 돕는 사람이 함께 있었습니다(느 8:7~8). 책이 퍼지는 길이 열리던 15세기에도 설교와 학교의 가르침, 번역과 인쇄처럼 읽는 일과 알아듣는 일을 잇는 길이 여럿 있었습니다.\n\n그리스도를 가리키는 자리는 누가복음 24:27입니다. 엠마오로 가던 두 제자에게 부활하신 예수께서 모세 오경과 예언서부터 시작해 구약 성경 전체를 따라 자기가 어떤 분인지를 풀어 주셨습니다. 에스라의 마당에서 읽히던 책도 그 풀이 안에 있었습니다.\n\n우리와 같은 것, 다른 것. 웨스트민스터 신앙고백은 구약은 히브리어로, 신약은 그리스어로 기록되었고 원어를 모르는 백성이 성경을 읽고 살피도록 모든 나라 말로 옮겨져야 한다고 말하고(1장 8절), 보이는 교회는 온 세상에서 참된 종교를 고백하는 이들로 이루어진다고 말합니다(25장 2절).⁶ 다른 것은 가톨릭이 성경과 전승을 같은 원천에서 나온 것으로 함께 공경하고 해석을 교황과 하나 된 주교들의 가르치는 직분에 맡긴다고 설명하는 점입니다.⁷ 이 책은 느헤미야 8장의 모임에서 1517년 앞의 교회까지 같은 교회의 길이 이어지고 있다고 읽고, 우리 교회가 어떤 입장을 더할지는 교역자와 나눕니다.",
